input.newString:
function setStatus(id: number, status: 'fulfilled' | 'deleted'): ListingRow | undefined {
  const db = getDb();

  // Get the current status of the listing
  const currentListing = getListingById(id);
  if (!currentListing) {
    return undefined;
  }

  const currentStatus = currentListing.status;

  // Define valid status transitions
  const validTransitions: Record<string, Set<string>> = {
    'active': new Set(['fulfilled', 'deleted']),
    'fulfilled': new Set(['deleted']),
  };

  // Check if the transition is valid
  if (currentStatus === status) {
    // Same status - no transition needed, but we should still update the updatedAt timestamp
    db.update(listings).set({ updatedAt: now() }).where(eq(listings.id, id)).run();
    return getListingById(id);
  }

  // Check if current status is in our valid transitions map
  const allowedTransitions = validTransitions[currentStatus];
  if (!allowedTransitions || !allowedTransitions.has(status)) {
    throw new Error(
      `Cannot transition listing #${id} from status "${currentStatus}" to "${status}".`,
    );
  }

  db.update(listings).set({ status, updatedAt: now() }).where(eq(listings.id, id)).run();
  return getListingById(id);
}

